from routekit.build_adjacency import build_adjacency
from routekit.hop_distances import hop_distances


def isolated_by_closures(edges: Iterable[Tuple[str, str, int]], depot: str, closed: Iterable[Tuple[str, str]], directed: bool = False) -> List[str]:
    """List depots cut off from ``depot`` by the given road closures.

    A depot is reported as isolated only if one of the closed roads is the
    road that directly connects it to the rest of the network reachable from
    ``depot`` (see design review / issue 388: a depot that merely loses a
    longer route but stays connected via another road is NOT cut off).
    """
    edges = list(edges)
    before = hop_distances(build_adjacency(edges, directed), depot)
    blocked = {frozenset(pair) for pair in closed}
    kept = [road for road in edges if frozenset(road[:2]) not in blocked]
    reduced = build_adjacency(kept, directed)
    after = hop_distances(reduced, depot) if depot in reduced else {depot: 0}

    lost = set(before) - set(after)

    # A lost depot is genuinely cut off only if a closed road is the one that
    # directly tied it to a still-reachable neighbour (the severed link).
    cut_off = set()
    for u, v in closed:
        for end, other in ((u, v), (v, u)):
            if end in lost and other in after:
                cut_off.add(end)
    return sorted(cut_off)
"}}, "messages": []}

